49	  const compiled = [];
50	  node.schema.fields.forEach((field, index) => {
51	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
52	    if (!isUsableObject(field)) {
