366	// An action node either keeps the legacy `message` behavior, names a business
367	// operation the caller supplies at run time, and/or declares a compensation
368	// operation that undoes its business effect. Both retry blocks are optional
369	// and, absent, mean exactly one attempt with no waiting.
370	function compileAction(node) {
371	  let name = null;
372	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
373	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
374	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
375	    }
376	    name = node.operation;
377	  }
378	
379	  let retry = { ...DEFAULT_RETRY };
380	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
381	    if (!name) {
382	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
383	    }
384	    retry = compileRetry(node.retry, `action node ${node.id}`);
385	  }
386	
387	  let compensation = null;
388	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
389	    if (!isUsableObject(node.compensation)) {
390	      throw new Error(`action node ${node.id}: compensation must be an object`);
391	    }
392	    if (!name) {
393	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
394	    }
395	    const config = node.compensation;
396	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
397	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
398	    }
399	    let compRetry = { ...DEFAULT_RETRY };
400	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
401	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
402	    }
403	    compensation = { name: config.operation, retry: compRetry };
404	  }
405	
406	  // A legacy message action (no operation) is validated through the single
407	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
408	  // action-specific wording, that end-node results use — covering every
409	  // message action including ones on untaken branches and entry-unreachable
410	  // ones. An action that names an operation ignores its message entirely, so
411	  // an unused uncloneable or shared-memory message is never rejected for it.
412	  // The gate only proves the message was safe as it was then; the same rule
413	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
414	  if (name === null) {
415	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
416	  }
417	
418	  return { name, retry, compensation };
419	}
420	
421	// The two failure kinds a node-configured value can produce, shared by
422	// definition validation (assertConfiguredCopy below) and the execution-time
423	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
424	// all, or it clones but the clone retains shared memory. Uncloneability takes
425	// precedence when a value carries both, at both moments. Each node kind keeps
426	// its own wording — an action's message and an end node's result fail with the
427	// node-specific text the entries already exposed — and its own default for a
428	// value that is absent, undefined or null (action:<node id> for a legacy
429	// message; null for an end result), while "", 0 and false pass through
430	// untouched for both.
431	const ACTION_MESSAGE_COPY_ERRORS = {
432	  uncloneable: nodeId =>
433	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
434	  sharedMemory: nodeId =>
435	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
436	};
437	const END_RESULT_COPY_ERRORS = {
438	  uncloneable: nodeId =>
439	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
440	  sharedMemory: nodeId =>
441	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
442	};
443	
444	// The single independent-copy rule for a value a node configures — a legacy
445	// action's `message` and an end node's `result` both go through here, so the
446	// cloneability and retained-shared-memory rules are maintained in exactly one
447	// place and the two node kinds can never drift apart. It is invoked at two
448	// moments, and each moment keeps its original root-read protocol:
449	//
450	//  1. At validation time (assertConfiguredCopy), for every such node in the
451	//     definition — including nodes on untaken branches and nodes the entry
452	//     cannot reach — so a statically invalid value is rejected before any
453	//     node, business operation or compensation can run. An absent own
454	//     property is not read at all; the gate performs the first root read and
455	//     only an own, defined value reaches the clone, which performs the root's
456	//     second read itself (a throwing root accessor propagates from the gate
457	//     exactly as before).
458	//  2. At the node's own execution moment (readConfiguredCopy), against the
459	//     value actually about to be saved: the root is read exactly once and the
460	//     value that read produced is cloned, so validation cannot pin the result
461	//     — an enumerable getter's later answer and a preceding business
462	//     operation's or another activated branch's mutation are both captured.
463	//
464	// At either moment every nested enumerable accessor is read only by
465	// structuredClone's own read — there is no separate inspection pass over the
466	// original, so a getter's return order is never disturbed and the value the
467	// clone's read produced is both what is judged and what is saved (a legal
468	// value whose getter answers with a different ordinary value at execution
469	// time records that fresh value rather than the stale validation-time one). A
470	// root getter that throws on execution's single read, a nested getter that
471	// throws while the clone reads it, and a value that cannot be cloned at all
472	// (a bare function) all surface as the same uncloneable error.
473	//
474	// The copy itself is produced by independentCopy — the one clone-then-judge
475	// rule every saved value in this engine goes through (see its comment for why
476	// cloning must precede the shared-memory traversal and why uncloneability
477	// takes precedence). Only the wording of the failure is node-specific here.
478	//
479	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
480	// rather than recorded as a run status: the synchronous entry propagates it
481	// and the asynchronous entry's rejected Promise carries it. It is never an
482	// action_failed — neither node kind has a retry budget — it neither consumes
483	// business-action retries nor triggers compensation, and no output/result is
484	// recorded for the node. At execution, an absent, undefined or null value
485	// becomes `absentValue` (action:<node id> for messages, null for results),
486	// while "", 0 and false pass through untouched.
487	function configuredCopy(node, property, errors, options) {
488	  const validation = options !== undefined && options.validation === true;
489	
490	  if (validation) {
491	    // Preserve the validation gate exactly: no read at all for a missing own
492	    // property, one unguarded gate read (a throwing root accessor propagates
493	    // raw, as the former per-node gates did), and an undefined value is left
494	    // to execution. The structuredClone argument evaluation is the root's
495	    // second — and final — read this moment; the clone itself traverses that
496	    // captured value (firing nested getters once), so no read the original
497	    // gate made is added or removed.
498	    if (!Object.hasOwn(node, property)) return;
499	    const gated = node[property];
500	    if (gated === undefined) return;
501	    const copy = independentCopy(node[property]);
502	    if (!copy.ok) throw new Error(errors[copy.reason](node.id));
503	    return;
504	  }
505	
506	  // Execution: the root value's single read. An absent, undefined or null
