2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// Shared shape for both entry points:
6	//
7	//   start -> prep (message action) -> form-one (succeeds, applies defaults)
8	//         -> reserve (business action + compensation in async runs; a message
9	//                    action in sync runs)
10	//         -> form-two (succeeds, applies more defaults)
11	//         -> form-three (applies several defaults, then fails validation)
12	//         -> after (end, never reached)
13	//
14	// The failing form exercises every rollback boundary:
15	// - brand.new.deep / fresh.pair.x / fresh.pair.y create wholly new parent
16	//   chains, one with two sibling fields written by the failed form itself;
17	// - shared.leaf lands in a parent object the caller supplied;
18	// - later.temp lands in a parent an earlier successful form created;
19	// - missing.required is a missing required value;
20	// - count is present but wrong-typed despite carrying a default;
21	// - sized is present but violates its length constraint.
22	function rollbackWorkflow(reserveNode) {
23	  return {
24	    id: 'form-rollback-regression',
25	    entry: 'start',
26	    nodes: [
27	      { id: 'start', type: 'trigger', next: 'prep' },
28	      { id: 'prep', type: 'action', message: 'prepared', next: 'form-one' },
29	      { id: 'form-one', type: 'form', next: 'reserve', schema: { fields: [
30	        { path: 'one.top', type: 'string', default: 'A' },
31	        { path: 'flat', type: 'integer', default: 1 },
32	      ] } },
33	      reserveNode,
34	      { id: 'form-two', type: 'form', next: 'form-three', schema: { fields: [
35	        { path: 'later.keep', type: 'string', default: 'B' },
36	      ] } },
37	      { id: 'form-three', type: 'form', next: 'after', schema: { fields: [
38	        { path: 'brand.new.deep', type: 'string', default: 'deep' },
39	        { path: 'fresh.pair.x', type: 'string', default: 'x' },
40	        { path: 'fresh.pair.y', type: 'string', default: 'y' },
41	        { path: 'shared.leaf', type: 'string', default: 'leaf' },
42	        { path: 'later.temp', type: 'string', default: 'T' },
43	        { path: 'missing.required', type: 'string', required: true },
44	        { path: 'count', type: 'integer', default: 7 },
45	        { path: 'sized', type: 'string', maxLength: 3 },
46	      ] } },
47	      { id: 'after', type: 'end', result: 'done' },
48	    ],
49	  };
50	}
