81	function assertRolledBackInput(result) {
82	  assert.deepEqual(result.context.input, expectedRolledBackInput());
83	
84	  // Parent chains created solely for the failed form's defaults disappear
85	  // completely — including a parent that held two of that form's defaults.
86	  assert.equal(Object.hasOwn(result.context.input, 'brand'), false);
87	  assert.equal(Object.hasOwn(result.context.input, 'fresh'), false);
88	  assert.equal(Object.hasOwn(result.context.input, 'missing'), false);
89	
90	  // A pre-existing parent keeps its original children but loses the leaf the
91	  // failed form added.
