93	  // A parent an earlier form created survives with that form's child; the
94	  // failed form's sibling is gone.
95	  assert.deepEqual(result.context.input.later, { keep: 'B' });
96	
97	  // The present-but-wrong-typed value is kept as-is: it was not treated as
98	  // missing, so the integer default never replaced it.
99	  assert.equal(result.context.input.count, 'many');
100	}
