102	test('async run: a failed form rolls back only its own defaults while compensation uses the success-time snapshot', async () => {
103	  const workflow = rollbackWorkflow({
104	    id: 'reserve', type: 'action', operation: 'reserve',
105	    compensation: { operation: 'release' }, next: 'form-two',
