1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from '../src/engine.js';
4	
5	const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
6	
7	// A trigger -> legacy message action -> end workflow usable by the
8	// synchronous entry.
9	function linearMessageWorkflow(message, { omit = false } = {}) {
10	  return {
11	    id: 'linear-message',
12	    entry: 'start',
13	    nodes: [
14	      { id: 'start', type: 'trigger', next: 'note' },
