  const runPromise = executeWorkflowAsync(workflow, { amount: 15 }, hold.operations);
  await hold.started;
  await sleep(5);

  formNode.schema.fields[0].min = 20;
  formNode.schema.fields[1].default = 'api';
  ghostNode.next = 'nowhere';
